import json, os
root='/private/tmp/opensip-design-corrections/consumer-b.v24/subject/docs/'
out='/private/tmp/opensip-design-corrections/consumer-b.v24/output/notes/'
def short(v):
    s=json.dumps(v,ensure_ascii=False,sort_keys=True)
    return s if len(s)<=240 else s[:237]+'...'
def prop_line(name,p):
    keys=[]
    if not isinstance(p,dict): return f"  {name}: {short(p)}"
    for k in ('type','const','enum','pattern','$ref','minItems','maxItems','minimum','maximum','minLength','maxLength','uniqueItems','x-opensip-order','x-opensip-digest','oneOf','anyOf','items','additionalProperties','required','properties'):
        if k in p:
            v=p[k]
            if k=='properties': v=sorted(v.keys())
            if k=='items' and isinstance(v,dict): v={kk:vv for kk,vv in v.items() if kk in('$ref','type','x-opensip-order','enum','pattern','x-opensip-digest','required')}
            keys.append(f"{k}={short(v)}")
    extra=[k for k in p if k.startswith('x-opensip') and k not in('x-opensip-order','x-opensip-digest')]
    for k in extra: keys.append(f"{k}={short(p[k])}")
    return f"  {name}: "+' | '.join(keys)
def dump(rel):
    d=json.load(open(root+rel))
    lines=[f"# {rel}", "top-level keys: "+', '.join(d.keys())]
    for k,v in d.items():
        if k in('$defs','definitions'): continue
        if k.startswith('x-opensip') or k in ('properties','required','type'):
            lines.append(f"## {k}: {short(v) if not isinstance(v,dict) else 'keys='+short(list(v.keys()))}")
    defs=d.get('$defs',{})
    for name,s in defs.items():
        if not isinstance(s,dict): lines.append(f"### {name}: {short(s)}"); continue
        hdr=[f"### {name}"]
        for k in ('type','required','additionalProperties','oneOf','anyOf','allOf','enum','const','pattern','$ref','x-opensip-order','items','description'):
            if k in s:
                v=s[k]
                if k=='description': v=v[:300]
                hdr.append(f"{k}={short(v)}")
        for k in s:
            if k.startswith('x-opensip') and k!='x-opensip-order': hdr.append(f"{k}={short(s[k])}")
        lines.append(' | '.join(hdr))
        for pn,p in s.get('properties',{}).items():
            lines.append(prop_line(pn,p))
    return '\n'.join(lines)
files=['coop/design-corrections/foundation/identity-schemas.v3.json','coop/design-corrections/native/native-evidence.schemas.v2.json','coop/design-corrections/foundation/relation-payload-schemas.v2.json','coop/design-corrections/workflows/schemas/evaluator3/common.schema.json','coop/design-corrections/workflows/schemas/policy-document.v2.schema.json','coop/design-corrections/workflows/schemas/policy-document.schema.json','coop/design-corrections/foundation/enumeration-plan.schema.v1.json','coop/design-corrections/foundation/subject-inventory.schema.v1.json','coop/design-corrections/foundation/execution-inputs.schema.v1.json','coop/design-corrections/foundation/evaluator-emission-plan.schema.v1.json','coop/design-corrections/workflows/schemas/evaluator3/graph-query.schema.json','coop/design-corrections/workflows/schemas/evaluator3/command-envelope.schema.json','coop/design-corrections/workflows/schemas/imported-evidence.schema.json','coop/design-corrections/foundation/evaluator-fault-observation.schema.v3.json','coop/design-corrections/foundation/target-attribution.schema.v2.json','coop/design-corrections/native/fact-batch.schema.v3.json','coop/design-corrections/native/occupancy-companion.schema.v1.json','coop/design-corrections/native/dispatch-binding.schema.v1.json','coop/design-corrections/foundation/incoming-search.schema.v1.json','coop/design-corrections/workflows/schemas/evaluator3/invocation-record.schema.json','coop/design-corrections/workflows/schemas/evaluator3/comparison-result.schema.json','coop/design-corrections/workflows/schemas/evaluator3/baseline-artifact.schema.json','coop/design-corrections/workflows/schemas/evaluator3/repair.schema.json','coop/design-corrections/workflows/schemas/evaluator3/detector-manifest.schema.json','coop/design-corrections/foundation/product-configuration.schema.v2.json','coop/design-corrections/foundation/import-source-context.schema.json','coop/design-corrections/workflows/schemas/test-execution.schema.json','coop/design-corrections/foundation/provider-target-attribution-return.schema.v2.json']
os.makedirs(out+'schemas',exist_ok=True)
for f in files:
    txt=dump(f)
    fn=out+'schemas/'+f.split('/')[-2]+'__'+f.split('/')[-1]+'.txt'
    open(fn,'w').write(txt)
    print(len(txt.splitlines()), len(txt), fn.split('notes/')[1])
EOF
